import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.URL;
import java.util.Arrays;
import java.util.List;

public class SecureRequest {
    private static final List<String> ALLOWED_SCHEMES = Arrays.asList("http", "https");

    public static void main(String[] args) throws Exception {
        String userInput = "http://example.com/data";

        // Validate the scheme before constructing the URL
        if (!isAllowedScheme(userInput)) {
            throw new IllegalArgumentException("Invalid scheme in request");
        }

        URL url = new URL(userInput);

        // Perform DNS resolution to check for private or loopback addresses
        InetAddress address = InetAddress.getByName(url.getHost());
        if (address.isLoopbackAddress() || address.isAnyLocalAddress() || address.isSiteLocalAddress()) {
            throw new IllegalArgumentException("Access to internal network is forbidden");
        }

        BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()));
        System.out.println(reader.readLine());
    }

    private static boolean isAllowedScheme(String urlString) {
        try {
            URL url = new URL(urlString);
            return ALLOWED_SCHEMES.contains(url.getProtocol().toLowerCase());
        } catch (Exception e) {
            return false;
        }
    }
}
